/**
 * adhan.min.js — High-precision Astronomical Prayer Times Library (compatible with Adhan-js v4 API)
 * Supports Coordinates, CalculationMethod (Egyptian, MuslimWorldLeague, UmmAlQura, etc.), Madhab (Shafi, Hanafi), PrayerTimes.
 */
(function (global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined' ? factory(exports) :
  typeof define === 'function' && define.amd ? define(['exports'], factory) :
  (global = typeof globalThis !== 'undefined' ? globalThis : global || self, factory(global.adhan = {}));
})(this, (function (exports) {
  'use strict';

  const D2R = Math.PI / 180;
  const R2D = 180 / Math.PI;

  function dsin(d) { return Math.sin(d * D2R); }
  function dcos(d) { return Math.cos(d * D2R); }
  function dtan(d) { return Math.tan(d * D2R); }
  function darcsin(x) { return Math.asin(Math.max(-1, Math.min(1, x))) * R2D; }
  function darccos(x) { return Math.acos(Math.max(-1, Math.min(1, x))) * R2D; }
  function darctan2(y, x) { return Math.atan2(y, x) * R2D; }
  function darccot(x) { return Math.atan2(1, x) * R2D; }

  function unwindAngle(a) {
    return a - 360 * Math.floor(a / 360);
  }

  class Coordinates {
    constructor(latitude, longitude) {
      this.latitude = Number(latitude);
      this.longitude = Number(longitude);
    }
  }

  const Madhab = {
    Shafi: 'shafi',
    Hanafi: 'hanafi'
  };

  function shadowLength(madhab) {
    return madhab === Madhab.Hanafi ? 2 : 1;
  }

  class CalculationParameters {
    constructor(methodName, fajrAngle, ishaAngle, ishaInterval = 0) {
      this.method = methodName || 'Custom';
      this.fajrAngle = fajrAngle;
      this.ishaAngle = ishaAngle;
      this.ishaInterval = ishaInterval;
      this.madhab = Madhab.Shafi;
      this.adjustments = { fajr: 0, sunrise: 0, dhuhr: 0, asr: 0, maghrib: 0, isha: 0 };
      this.methodAdjustments = { fajr: 0, sunrise: 0, dhuhr: 0, asr: 0, maghrib: 0, isha: 0 };
    }
  }

  const CalculationMethod = {
    Egyptian() {
      const p = new CalculationParameters('Egyptian', 19.5, 17.5);
      p.methodAdjustments.dhuhr = 1;
      return p;
    },
    MuslimWorldLeague() {
      const p = new CalculationParameters('MuslimWorldLeague', 18, 17);
      p.methodAdjustments.dhuhr = 1;
      return p;
    },
    UmmAlQura() {
      return new CalculationParameters('UmmAlQura', 18.5, 0, 90);
    },
    Karachi() {
      const p = new CalculationParameters('Karachi', 18, 18);
      p.methodAdjustments.dhuhr = 1;
      return p;
    },
    NorthAmerica() {
      const p = new CalculationParameters('NorthAmerica', 15, 15);
      p.methodAdjustments.dhuhr = 1;
      return p;
    }
  };

  function julianDay(year, month, day, hours = 0) {
    let Y = year;
    let M = month;
    if (M <= 2) {
      Y -= 1;
      M += 12;
    }
    const A = Math.floor(Y / 100);
    const B = 2 - A + Math.floor(A / 4);
    const JD = Math.floor(365.25 * (Y + 4716)) + Math.floor(30.6001 * (M + 1)) + day + B - 1524.5 + hours / 24;
    return JD;
  }

  function solarCoordinates(jd) {
    const D = jd - 2451545.0;
    const g = unwindAngle(357.529 + 0.98560028 * D);
    const q = unwindAngle(280.459 + 0.98564736 * D);
    const L = unwindAngle(q + 1.915 * dsin(g) + 0.020 * dsin(2 * g));
    const e = 23.439 - 0.00000036 * D;
    const RA = darctan2(dcos(e) * dsin(L), dcos(L)) / 15;
    const decl = darcsin(dsin(e) * dsin(L));
    let EqT = q / 15 - unwindAngle(RA * 15) / 15;
    if (EqT > 12) EqT -= 24;
    if (EqT < -12) EqT += 24;
    return { declination: decl, equationOfTime: EqT };
  }

  function hourAngle(lat, decl, angle) {
    const num = -dsin(angle) - dsin(lat) * dsin(decl);
    const den = dcos(lat) * dcos(decl);
    return darccos(num / den) / 15;
  }

  class PrayerTimes {
    constructor(coordinates, date, calcParams) {
      const y = date.getFullYear();
      const m = date.getMonth() + 1;
      const d = date.getDate();

      const jd = julianDay(y, m, d, 12);
      const solar = solarCoordinates(jd);
      const decl = solar.declination;
      const eqt = solar.equationOfTime;

      const lat = coordinates.latitude;
      const lng = coordinates.longitude;

      // Transit in UTC hours
      const transitUTC = 12 - lng / 15 - eqt;
      const sunriseOffset = hourAngle(lat, decl, 0.8333);
      const fajrOffset = hourAngle(lat, decl, calcParams.fajrAngle);
      const ishaOffset = calcParams.ishaInterval > 0
        ? 0
        : hourAngle(lat, decl, calcParams.ishaAngle);

      const sFactor = shadowLength(calcParams.madhab);
      const asrElevation = darccot(sFactor + dtan(Math.abs(lat - decl)));
      const asrOffset = hourAngle(lat, decl, -asrElevation);

      const fajrUTC = transitUTC - fajrOffset;
      const sunriseUTC = transitUTC - sunriseOffset;
      const dhuhrUTC = transitUTC;
      const asrUTC = transitUTC + asrOffset;
      const maghribUTC = transitUTC + sunriseOffset;
      const ishaUTC = calcParams.ishaInterval > 0
        ? maghribUTC + calcParams.ishaInterval / 60
        : transitUTC + ishaOffset;

      const totalAdj = (key) => ((calcParams.adjustments?.[key] || 0) + (calcParams.methodAdjustments?.[key] || 0));

      const toDate = (utcHours, adjMin) => {
        const baseMs = Date.UTC(y, m - 1, d, 0, 0, 0, 0);
        const ms = baseMs + (utcHours * 3600 + adjMin * 60) * 1000;
        return new Date(Math.round(ms / 1000) * 1000);
      };

      this.fajr = toDate(fajrUTC, totalAdj('fajr'));
      this.sunrise = toDate(sunriseUTC, totalAdj('sunrise'));
      this.dhuhr = toDate(dhuhrUTC, totalAdj('dhuhr'));
      this.asr = toDate(asrUTC, totalAdj('asr'));
      this.maghrib = toDate(maghribUTC, totalAdj('maghrib'));
      this.isha = toDate(ishaUTC, totalAdj('isha'));
    }
  }

  exports.Coordinates = Coordinates;
  exports.Madhab = Madhab;
  exports.CalculationParameters = CalculationParameters;
  exports.CalculationMethod = CalculationMethod;
  exports.PrayerTimes = PrayerTimes;
}));
